    (18, "输出单词长度分布。", "words = [\"hi\", \"hello\", \"world\", \"python\", \"programming\"]\nfor w in words:\n    print(f\"{w:<12}{len(w):>3} {'*' * len(w)}\")", "填空分布格式。", "words = [\"hi\", \"hello\", \"world\", \"python\", \"programming\"]\nfor w in words:\n    print(f\"{w:<12}{len(w):>3} {'*' * len(w)}\")"),
    (19, "格式化输出日期。", "year, month, day = 2026, 8, 12\nprint(f\"{year}-{month:02d}-{day:02d}\")\nprint(f\"{month}/{day}/{year}\")", "填空日期格式。", "year, month, day = 2026, 8, 12\nprint(f\"{year}-{month:02d}-{day:02d}\")\nprint(f\"{month}/{day}/{year}\")"),
    (20, "输出数字金字塔（居中）。", "n = 5\nfor i in range(1, n + 1):\n    line = \"\".join(str(j) for j in range(1, i + 1))\n    print(f\"{line:^{2 * n}}\")", "填空居中宽度。", "n = 5\nfor i in range(1, n + 1):\n    line = \"\".join(str(j) for j in range(1, i + 1))\n    print(f\"{line:^{2 * n}}\")"),
    (21, "输出三列对齐数据。", "rows = [(\"Tom\", 25, \"BEIJING\"), (\"Ada\", 36, \"LONDON\")]\nprint(f\"{'Name':<8}{'Age':>5}{'City':>10}\")\nfor name, age, city in rows:\n    print(f\"{name:<8}{age:>5}{city:>10}\")", "填空三列对齐。", "rows = [(\"Tom\", 25, \"BEIJING\"), (\"Ada\", 36, \"LONDON\")]\nprint(f\"{'Name':<8}{'Age':>5}{'City':>10}\")\nfor name, age, city in rows:\n    print(f\"{name:<8}{age:>5}{city:>10}\")"),
    (22, "格式化输出百分比成绩。", "scores = [(\"quiz1\", 8, 10), (\"quiz2\", 9, 10)]\nfor name, got, total in scores:\n    print(f\"{name:<6}{got}/{total} = {got / total:.0%}\")", "填空百分比格式。", "scores = [(\"quiz1\", 8, 10), (\"quiz2\", 9, 10)]\nfor name, got, total in scores:\n    print(f\"{name:<6}{got}/{total} = {got / total:.0%}\")"),
    (23, "把浮点数表格式化为整数表。", "values = [3.7, 2.1, 9.9, 1.5]\nfor v in values:\n    print(f\"{v:>6.1f} -> {v:>5.0f}\")", "填空双格式。", "values = [3.7, 2.1, 9.9, 1.5]\nfor v in values:\n    print(f\"{v:>6.1f} -> {v:>5.0f}\")"),
    (24, "输出缩进的目录结构。", "tree = [(\"src\", 0), (\"main.py\", 1), (\"utils\", 1), (\"helper.py\", 2)]\nfor name, level in tree:\n    print(\"  \" * level + name)", "填空缩进生成。", "tree = [(\"src\", 0), (\"main.py\", 1), (\"utils\", 1), (\"helper.py\", 2)]\nfor name, level in tree:\n    print(\"  \" * level + name)"),
    (25, "格式化输出收支报表。", "flows = [(\"Jan\", 8000, 6000), (\"Feb\", 9000, 7500)]\nprint(f\"{'Month':<6}{'Income':>10}{'Expense':>10}{'Net':>8}\")\nfor month, inc, exp in flows:\n    print(f\"{month:<6}{inc:>10,d}{exp:>10,d}{inc - exp:>8,d}\")", "填空报表格式。", "flows = [(\"Jan\", 8000, 6000), (\"Feb\", 9000, 7500)]\nprint(f\"{'Month':<6}{'Income':>10}{'Expense':>10}{'Net':>8}\")\nfor month, inc, exp in flows:\n    print(f\"{month:<6}{inc:>10,d}{exp:>10,d}{inc - exp:>8,d}\")"),
    (26, "输出居中菱形（字符）。", "n = 3\nfor i in range(1, n + 1):\n    print(f\"{'*' * (2 * i - 1):^{2 * n - 1}}\")\nfor i in range(n - 1, 0, -1):\n    print(f\"{'*' * (2 * i - 1):^{2 * n - 1}}\")", "填空居中格式。", "n = 3\nfor i in range(1, n + 1):\n    print(f\"{'*' * (2 * i - 1):^{2 * n - 1}}\")\nfor i in range(n - 1, 0, -1):\n    print(f\"{'*' * (2 * i - 1):^{2 * n - 1}}\")"),
    (27, "输出数字与平方立方对照表。", "print(f\"{'n':>3}{'sq':>6}{'cube':>8}\")\nfor n in range(1, 6):\n    print(f\"{n:>3}{n ** 2:>6}{n ** 3:>8}\")", "填空对照表格式。", "print(f\"{'n':>3}{'sq':>6}{'cube':>8}\")\nfor n in range(1, 6):\n    print(f\"{n:>3}{n ** 2:>6}{n ** 3:>8}\")"),
