    (29, "用格式输出字母三角形。", "for i in range(1, 6):\n    line = \"\".join(chr(64 + j) for j in range(1, i + 1))\n    print(f\"{line:^10}\")", "填空居中输出。", "for i in range(1, 6):\n    line = \"\".join(chr(64 + j) for j in range(1, i + 1))\n    print(f\"{line:^10}\")"),
    (30, "综合格式化输出统计报告。", "data = {\"total\": 120, \"passed\": 96, \"failed\": 24}\nrate = data[\"passed\"] / data[\"total\"]\nprint(f\"Total: {data['total']}\")\nprint(f\"Passed: {data['passed']} ({rate:.1%})\")\nprint(f\"Failed: {data['failed']} ({1 - rate:.1%})\")", "填空综合报告。", "data = {\"total\": 120, \"passed\": 96, \"failed\": 24}\nrate = data[\"passed\"] / data[\"total\"]\nprint(f\"Total: {data['total']}\")\nprint(f\"Passed: {data['passed']} ({rate:.1%})\")\nprint(f\"Failed: {data['failed']} ({1 - rate:.1%})\")"),
